int sum = 0, num;
while (true) {
    System.out.print("Enter a number to add (0 to stop): ");
    num = console.nextInt();
    if (num == 0) {
        System.out.println("Done.");
        break;
    }
    sum = sum + num;
}

int sum = 0, num;
while (true) {
    System.out.print("Enter a number (0 to stop, no negatives): ");
    num = console.nextInt();
    if (num == 0) {
        break;
    } else if (num < 0) {
        System.out.println("Negative numbers aren't allowed.");
        continue;
    }
    sum = sum + num;
}
